from __future__ import annotations

import ipaddress
import platform
import re
import socket
import subprocess

from secretscan.model import LANDevice, Module, ModuleStatus, NetworkInterface

_MAX_SWEEP_HOSTS = 1024


def _get_interfaces() -> list[NetworkInterface]:
    interfaces: list[NetworkInterface] = []
    system = platform.system()

    if system == "Windows":
        try:
            result = subprocess.run(
                ["ipconfig"], capture_output=True, text=True, timeout=10,
            )
            current_name = ""
            for line in result.stdout.splitlines():
                if line and not line[0].isspace() and ":" in line:
                    current_name = line.split(":")[0].strip()
                elif "IPv4 Address" in line and ":" in line:
                    addr = line.split(":")[-1].strip()
                    if addr and not addr.startswith("127."):
                        interfaces.append(NetworkInterface(
                            name=current_name, address=addr,
                            netmask="255.255.255.0",
                        ))
                elif "Subnet Mask" in line and interfaces and ":" in line:
                    interfaces[-1].netmask = line.split(":")[-1].strip()
        except Exception:
            pass
    else:
        try:
            result = subprocess.run(
                ["ifconfig"], capture_output=True, text=True, timeout=10,
            )
            current_name = ""
            for line in result.stdout.splitlines():
                if line and not line[0].isspace():
                    current_name = line.split(":")[0]
                elif "inet " in line and "127.0.0.1" not in line:
                    parts = line.split()
                    addr = ""
                    netmask = ""
                    broadcast = ""
                    for i, p in enumerate(parts):
                        if p == "inet" and i + 1 < len(parts):
                            addr = parts[i + 1]
                        elif p == "netmask" and i + 1 < len(parts):
                            netmask = parts[i + 1]
                        elif p == "broadcast" and i + 1 < len(parts):
                            broadcast = parts[i + 1]
                    if addr:
                        interfaces.append(NetworkInterface(
                            name=current_name, address=addr,
                            netmask=netmask, broadcast=broadcast,
                        ))
        except Exception:
            pass
    return interfaces


def _netmask_to_prefix(netmask_hex: str) -> int:
    try:
        if netmask_hex.startswith("0x"):
            mask_int = int(netmask_hex, 16)
            return bin(mask_int).count("1")
        addr = ipaddress.IPv4Address(netmask_hex)
        return bin(int(addr)).count("1")
    except Exception:
        return 24


def _ping_sweep(network: str) -> None:
    system = platform.system()
    try:
        net = ipaddress.IPv4Network(network, strict=False)
        if net.num_addresses > _MAX_SWEEP_HOSTS:
            return
        for host in net.hosts():
            try:
                if system == "Windows":
                    subprocess.run(
                        ["ping", "-n", "1", "-w", "1000", str(host)],
                        capture_output=True, timeout=2,
                    )
                else:
                    subprocess.run(
                        ["ping", "-c", "1", "-W", "1", str(host)],
                        capture_output=True, timeout=2,
                    )
            except Exception:
                pass
    except Exception:
        pass


def _read_arp_cache() -> list[LANDevice]:
    devices: list[LANDevice] = []
    system = platform.system()

    try:
        result = subprocess.run(
            ["arp", "-a"], capture_output=True, text=True, timeout=10,
        )
        for line in result.stdout.splitlines():
            if system == "Windows":
                fields = line.split()
                if len(fields) >= 3:
                    ip = fields[0]
                    mac = fields[1]
                    try:
                        ipaddress.IPv4Address(ip)
                    except ValueError:
                        continue
                    if mac in ("ff-ff-ff-ff-ff-ff", "ff:ff:ff:ff:ff:ff"):
                        continue
                    hostname = ""
                    try:
                        hostname = socket.gethostbyaddr(ip)[0]
                    except Exception:
                        pass
                    devices.append(LANDevice(ip=ip, mac=mac, hostname=hostname))
            else:
                match = re.match(r"(\S+)\s+\((\d+\.\d+\.\d+\.\d+)\)\s+at\s+(\S+)", line)
                if not match:
                    continue
                hostname, ip, mac = match.group(1), match.group(2), match.group(3)
                if mac in ("ff:ff:ff:ff:ff:ff", "(incomplete)"):
                    continue
                if hostname == "?":
                    try:
                        hostname = socket.gethostbyaddr(ip)[0]
                    except Exception:
                        hostname = ""
                iface_match = re.search(r"on\s+(\S+)", line)
                iface = iface_match.group(1) if iface_match else ""
                devices.append(LANDevice(ip=ip, mac=mac, hostname=hostname, interface=iface))
    except Exception:
        pass
    return devices


def lan_scan() -> tuple[list[LANDevice], list[NetworkInterface], ModuleStatus]:
    status = ModuleStatus(module=Module.LAN)

    interfaces = _get_interfaces()
    status.note = (
        "actively probes other devices on your local network; "
        "this module sends traffic to hosts other than this machine"
    )

    for iface in interfaces:
        prefix = _netmask_to_prefix(iface.netmask)
        network = f"{iface.address}/{prefix}"
        status.attempted += 1
        _ping_sweep(network)
        status.accessed += 1

    devices = _read_arp_cache()
    return devices, interfaces, status
